-- Products added from extra's own product pages (read 2026-11-06 by the DOABNO page reader; robots.txt allows them).
-- Names in English and Arabic are the store's; the photo is the store's product image, credited to it.
-- No ratings: the site hides the stars until a source gives a real rating. Safe to run twice. Needs migration 0015.
-- Skipped: sony-wh1000xm6: page unreadable; huawei-watch-gt-6: no url; garmin-forerunner-965: page unreadable; xiaomi-vacuum-p30: page unreadable; delonghi-eletta-explore: page unreadable; dyson-airwrap-id: page unreadable

begin;

on conflict (id) do nothing;

on conflict (product_id, pos) do nothing;

on conflict (product_id, store_id) do update set url = excluded.url, active = true;

select 'extra', 'scrape', 'daily', null
where not exists (select 1 from public.feeds where store_id = 'extra' and format = 'scrape');

-- eXtra also sells the hair-care items listed here.
update public.stores set categories = array(select distinct unnest(categories || array['beauty']::text[])) where id = 'extra';

commit;
